        ("事件", ["序号", "时刻", "会话", "结果", "入队序", "前哈希", "哈希"]),
        ("会话", ["会话", "用户", "状态", "期限", "池", "地址", "租期"]),
        ("排队", ["会话", "用户", "申请时刻", "等待", "截止", "入队序"]),
    ):
